def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value or ""
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") != 1:
            return ""
        local, domain = value.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
        normalized = f"{local}@{domain}"

        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""
        return normalized

    def normalize_phone(value):
        value = value or ""
        match = re.search(r"x|ext|#", value, flags=re.IGNORECASE)
        if match:
            value = value[:match.start()]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = (value or "").strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = (value or "").strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def opted_out(value):
        return (value or "").strip().lower() in {"y", "yes", "true", "1"}

    prepared = []
    for index, row in enumerate(rows):
        email = normalize_email(row.get("email", ""))
        phone = normalize_phone(row.get("phone", ""))
        if not email and not phone:
            continue

        updated = parse_updated(row["updated"])
        prepared.append({
            "index": index,
            "row": row,
            "email": email,
            "phone": phone,
            "first_name": normalize_name(row.get("first_name", "")),
            "last_name": normalize_name(row.get("last_name", "")),
            "zip": normalize_zip(row.get("zip", "")),
            "source": (row.get("source", "") or "").strip().lower(),
            "updated_dt": updated,
            "opted_out": opted_out(row.get("opted_out", "")),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row.get("tags", "") or "")
                if tag.strip()
            },
        })

    # Union-find makes matching transitive across email and phone/name links.
    parent = list(range(len(prepared)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_owner = {}
    phone_name_owner = {}
    for i, contact in enumerate(prepared):
        if contact["email"]:
            if contact["email"] in email_owner:
                union(i, email_owner[contact["email"]])
            else:
                email_owner[contact["email"]] = i

        if contact["phone"] and contact["last_name"]:
            key = (contact["phone"], contact["last_name"].casefold())
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, contact in enumerate(prepared):
        groups.setdefault(find(i), []).append(contact)

    def choose(group, field, valid_only=False):
        candidates = [
            contact for contact in group
            if contact[field] and (not valid_only or contact[field])
        ]
        if not candidates:
            return ""
        best = min(
            candidates,
            key=lambda c: (
                c["source"] != "manual",
                -c["updated_dt"].timestamp(),
                c["index"],
            ),
        )
        return best[field]

    output = []
    for group in sorted(groups.values(), key=lambda g: min(c["index"] for c in g)):
        latest = max(c["updated_dt"] for c in group)
        output.append({
            "first_name": choose(group, "first_name"),
            "last_name": choose(group, "last_name"),
            "zip": choose(group, "zip"),
            "email": choose(group, "email"),
            "phone": choose(group, "phone"),
            "source": choose(group, "source"),
            "tags": ";".join(sorted(set().union(*(c["tags"] for c in group)))),
            "opted_out": "Y" if any(c["opted_out"] for c in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
